<?php
namespace App\Services;
use App\Support\MarketResearchCrudDefinitions as Defs;
use App\Support\MarketingCrudPermissions as P;
use Illuminate\Contracts\Auth\Authenticatable;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
final class MarketResearchCrudService {
 public function __construct(private readonly MarketResearchCrudAuthorization $policy,private readonly MarketingConfirmationTokenService $tokens,private readonly MarketResearchMutationAudit $audit) {}
 public function confirmation(Authenticatable $u,string $entity,string $action,int $client,int $id,array $payload): array { $perm=match($action){'create'=>P::MARKET_RESEARCH_CREATE,'update'=>P::MARKET_RESEARCH_UPDATE,'archive'=>P::MARKET_RESEARCH_ARCHIVE,'delete_permanent'=>P::MARKET_RESEARCH_DELETE_PERMANENT,default=>null}; abort_unless($perm,422); if(in_array($action,['archive','delete_permanent'],true)) $this->assertArchiveReason($payload['reason']??null); if($id){$r=$this->policy->object($u,$entity,$id,$perm);abort_unless((int)$r->produk_client_id===$client,403,'client_access_denied');}else{$this->policy->assert($u,$client,$perm);} $normalized=in_array($action,['archive','delete_permanent'],true)?['reason'=>$payload['reason']]:$payload; $token=$this->tokens->issue($u,$action,'market_research_'.$entity,$id,$this->hash($client,$normalized)); return ['action'=>$action,'module'=>'market_research_'.$entity,'record_id'=>$id,'client_id'=>$client,'expires_in'=>300,'confirmation_token'=>$token]; }
 public function create(Authenticatable $u,string $entity,array $d): array { $def=Defs::get($entity);$client=(int)$d['client_id'];$p=$this->payload($def,$d);$this->policy->assert($u,$client,P::MARKET_RESEARCH_CREATE);$this->tokens->consume($u,$d['confirmation_token'],'create','market_research_'.$entity,0,$this->hash($client,$p));$id=DB::table($def['table'])->insertGetId($p+['produk_client_id'=>$client,'created_at'=>now(),'updated_at'=>now()]);$this->audit->record($u,$entity,'CREATE',$id,$client,$p);return $this->read($def,$id); }
 public function update(Authenticatable $u,string $entity,int $id,array $d): array { $def=Defs::get($entity);$r=$this->policy->object($u,$entity,$id,P::MARKET_RESEARCH_UPDATE);abort_if($r->archived_at,409);abort_unless((int)$d['client_id']===(int)$r->produk_client_id,403,'client_id tidak sesuai.');$p=$this->payload($def,$d);$this->tokens->consume($u,$d['confirmation_token'],'update','market_research_'.$entity,$id,$this->hash((int)$r->produk_client_id,$p));DB::table($def['table'])->where('id',$id)->update($p+['updated_at'=>now()]);$this->audit->record($u,$entity,'UPDATE',$id,(int)$r->produk_client_id,$p);return $this->read($def,$id); }
 public function archive(Authenticatable $u,string $entity,int $id,array $d): array { $def=Defs::get($entity);$r=$this->policy->object($u,$entity,$id,P::MARKET_RESEARCH_ARCHIVE);abort_if(!$r,404,'record_not_found');abort_if($r->archived_at,409,'already_archived');$this->assertArchiveReason($d['reason']??null);$p=['reason'=>$d['reason']];$this->tokens->consume($u,$d['confirmation_token'],'archive','market_research_'.$entity,$id,$this->hash((int)$r->produk_client_id,$p));DB::table($def['table'])->where('id',$id)->update(['archived_at'=>now(),'archived_by'=>$u->getAuthIdentifier(),'updated_at'=>now()]);$this->audit->record($u,$entity,'ARCHIVE',$id,(int)$r->produk_client_id,$p);return ['id'=>$id,'archived'=>true]; }
 public function deletePermanent(Authenticatable $u,string $entity,int $id,array $d): array { $def=Defs::get($entity);$r=$this->policy->object($u,$entity,$id,P::MARKET_RESEARCH_DELETE);abort_if(!$r,404,'record_not_found');abort_if($r->archived_at,409,'already_archived');$client=(int)$r->produk_client_id;abort_unless($client===(int)$d['client_id'],403,'client_access_denied');$this->assertArchiveReason($d['reason']??null);$module='market_research_'.$entity;$p=['reason'=>$d['reason']];$this->tokens->consume($u,$d['confirmation_token'],'delete_permanent',$module,$id,$this->hash($client,$p));$deleted=DB::transaction(function()use($def,$entity,$id){$this->assertNoRelations($entity,$id);return DB::table($def['table'])->where('id',$id)->delete();});abort_unless($deleted===1,404,'record_not_found');$this->audit->record($u,$entity,'DELETE_PERMANENT',$id,$client,$p);return ['id'=>$id,'client_id'=>$client,'deleted_permanently'=>true]; }
 private function assertNoRelations(string $entity,int $id): void { if(Schema::hasTable('marketing_approval_events')&&DB::table('marketing_approval_events')->where('record_id',$id)->where('record_type',$entity)->exists())abort(409,'record_has_relations_archive_instead'); }
 private function assertArchiveReason(mixed $reason): void { abort_if(!is_string($reason)||trim($reason)==='',422,'reason_required'); abort_if(mb_strlen(trim($reason))<5||mb_strlen($reason)>500,422,'reason_invalid'); }
 private function payload(array $def,array $d): array{return array_filter(array_intersect_key($d,array_flip($def['fields'])),fn($v)=>$v!==null);}
 private function hash(int $c,array $p):string{return hash('sha256',json_encode(['client_id'=>$c,'payload'=>$p],JSON_THROW_ON_ERROR));}
 private function read(array $def,int $id):array{return(array)DB::table($def['table'])->where('id',$id)->first();}
}
